const body = $input.first().json.body || $input.first().json;
const requestId = body.request_id;
const feedId = body.feed_id;

if (!requestId || !feedId) {
  return [{ json: {
    status: 'BLOCKED',
    reason: 'MISSING_REQUIRED_FIELDS',
    message: 'request_id and feed_id are required to run post-submission verification.'
  }}];
}

return [{ json: {
  request_id: requestId,
  feed_id: feedId,
  verification_started_at: $now.toISO()
}}];

const validateInput = $('Validate Input').first().json;
const catalogItems = $input.all().map(function(i) { return i.json; });
const submissionItems = $('Fetch Submission Items').all().map(function(i) { return i.json; });

const itemResults = catalogItems.map(function(catalogData) {
  const matchingSubmissionItem = submissionItems.find(function(s) {
    return s.asin === catalogData.asin;
  }) || {};

  const expectedParentSku = matchingSubmissionItem.parent_sku || null;
  const relationships = catalogData.relationships || [];

  const isVerified = relationships.some(function(rel) {
    return rel.type === 'variation_child' && rel.parentAsins && rel.parentAsins.length > 0;
  });

  return {
    asin: catalogData.asin,
    sku: matchingSubmissionItem.sku || null,
    expected_parent_sku: expectedParentSku,
    relationships_found: relationships,
    relationship_count: relationships.length,
    is_verified: isVerified
  };
});

const allVerified = itemResults.length > 0 && itemResults.every(function(r) { return r.is_verified; });
const verificationStatus = allVerified ? 'verified_success' : 'unverified_manual_review';
const failedItems = itemResults.filter(function(r) { return !r.is_verified; });

const errors = failedItems.map(function(item) {
  return {
    asin: item.asin,
    sku: item.sku,
    message: 'Variation relationship not confirmed in Amazon catalog after feed processing for this ASIN.',
    action: 'Wait 15 more minutes and check Seller Central manually. If still not showing, open a Seller Support case.',
    needs_seller_support: true
  };
});

return [{ json: {
  request_id: validateInput.request_id,
  feed_id: validateInput.feed_id,
  verification_status: verificationStatus,
  expected_result: {
    request_id: validateInput.request_id,
    expected_relationship_type: 'variation_child',
    total_items_expected: submissionItems.length
  },
  actual_result: {
    items_checked: itemResults.length,
    items_verified: itemResults.length - failedItems.length,
    item_results: itemResults
  },
  errors: errors,
  verified_at: $now.toISO(),
  seller_id: submissionItems.length > 0 ? submissionItems[0].seller_id : null,
}}];

